// lib/core/services/table_export_xlsx.dart
//
// An ExportTable as a plain .xlsx (spec 2026-11-28 table export): one sheet,
// the title block, the table and the "Generated by" footer, written with
// xlsx_writer.dart.
import '../models/export_table.dart';
import 'xlsx_writer.dart';

/// The workbook's bytes. Throws [ExportTableException] on a row longer than
/// the columns.
List<int> buildTableXlsx(ExportTable t, {required String footer}) {
  final rows = exportRows(t);
  final cells = <String, Object?>{};
  var r = 1;
  void line(String text) => cells['A${r++}'] = text;

  line('BASA - ${t.title}');
  final place = exportPlaceLine(t);
  if (place != null) line(place);
  for (final f in t.filters) {
    line(f);
  }
  r++; // empty row
  for (var c = 0; c < t.columns.length; c++) {
    cells['${_col(c)}$r'] = t.columns[c].label;
  }
  r++;
  if (rows.isEmpty) line('No rows');
  for (final row in rows) {
    for (var c = 0; c < row.length; c++) {
      final v = row[c];
      if (v == null) continue;
      cells['${_col(c)}$r'] = t.columns[c].kind == ExportColumnKind.number && v is num ? v : '$v';
    }
    r++;
  }
  r++; // empty row
  line(footer);

  final widths = [
    for (var c = 0; c < t.columns.length; c++)
      ([t.columns[c].label.length, for (final row in rows) '${row[c] ?? ''}'.length].reduce((a, b) => a > b ? a : b) + 2)
          .clamp(8, 50)
          .toDouble(),
  ];
  return writeXlsx([
    XlsxSheetSpec(
      name: exportSheetName(t.title),
      cells: cells,
      textColumns: {
        for (var c = 0; c < t.columns.length; c++)
          if (t.columns[c].kind == ExportColumnKind.text) c + 1,
      },
      columnWidths: widths,
      printFooter: (left: footer, right: 'Page &P of &N'),
    ),
  ]);
}

/// The rows padded to the column count; a longer row is refused.
List<List<Object?>> exportRows(ExportTable t) => [
      for (final row in t.rows)
        if (row.length > t.columns.length)
          throw const ExportTableException('A row has more values than the table has columns.')
        else
          [...row, for (var i = row.length; i < t.columns.length; i++) null],
    ];

/// "ZZ School, school year 2026-2027", either part alone, or null.
String? exportPlaceLine(ExportTable t) => switch ((t.school, t.schoolYear)) {
      (null, null) => null,
      (final s?, null) => s,
      (null, final y?) => 'School year $y',
      (final s?, final y?) => '$s, school year $y',
    };

/// Excel's sheet name: `[ ] : * ? / \` removed, spaces collapsed, at most 31
/// characters, "Export" when nothing is left.
String exportSheetName(String title) {
  final name = title.replaceAll(RegExp(r'[\[\]:*?/\\]'), '').replaceAll(RegExp(r'\s+'), ' ').trim();
  final cut = name.length > 31 ? name.substring(0, 31).trim() : name;
  return cut.isEmpty ? 'Export' : cut;
}

String _col(int index) {
  var n = index + 1;
  var s = '';
  while (n > 0) {
    final m = (n - 1) % 26;
    s = String.fromCharCode(65 + m) + s;
    n = (n - 1) ~/ 26;
  }
  return s;
}
